import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { StewardshipService } from './stewardship.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="app-container">
      <!-- TRUST RAIL (Institutional Heartbeat) -->
      <header class="trust-rail">
        <div class="brand">
          <span class="logo">NEXUS ZTAN</span>
          <span class="status-label">OPERATIONAL PROVING GROUND</span>
        </div>

        <div class="metrics">
          <div class="metric">
            <label>TRUST LEVEL</label>
            <span [class]="'value ' + (state$ | async)?.trustLevel">{{ (state$ | async)?.trustLevel }}</span>
          </div>
          <div class="metric">
            <label>EPOCH</label>
            <span class="value">{{ (state$ | async)?.epoch }}</span>
          </div>
          <div class="metric">
            <label>SAFE_MODE</label>
            <span [class]="'value ' + ((state$ | async)?.isSafeMode ? 'ACTIVE' : 'INACTIVE')">
              {{ (state$ | async)?.isSafeMode ? 'ACTIVE' : 'INACTIVE' }}
            </span>
          </div>
          <div class="metric">
            <label>DRILL</label>
            <span class="value">{{ (state$ | async)?.activeDrill }}</span>
          </div>
        </div>
      </header>

      <main class="grid-layout">
        <!-- CHAOS PANEL (Left) -->
        <aside class="side-panel chaos-panel">
          <h3>CHAOS ENGINE</h3>
          <p class="panel-desc">Inject deterministic failure modes to validate system resilience.</p>

          <div class="drill-group">
            <button (click)="triggerDrill('IFD-001')">IFD-001: REPLAY DETERMINISM</button>
            <button (click)="triggerDrill('IFD-002')">IFD-002: COGNITIVE VALIDATION</button>
            <button (click)="triggerDrill('IFD-003')">IFD-003: GOVERNANCE CONVERGENCE</button>
            <button (click)="triggerDrill('IFD-004')">IFD-004: ADVERSARIAL REPLAY</button>
          </div>
        </aside>

        <!-- EVIDENCE VIEWER (Center) -->
        <section class="evidence-viewer">
          <div class="viewer-header">
            <div class="header-left">
              <h3>FORENSIC EVIDENCE LEDGER</h3>
              <span class="count">{{ (evidence$ | async)?.length }} entries</span>
            </div>

            <div class="replay-controls">
              <button class="ctrl-btn" title="Step Back">STEP BACK</button>
              <button class="ctrl-btn" title="Pause Stream">PAUSE</button>
              <button class="ctrl-btn" title="Step Forward">STEP FORWARD</button>
              <button class="ctrl-btn highlight" title="Reconstruct State">RECONSTRUCT</button>
            </div>
          </div>

          <div class="evidence-list">
            <div *ngFor="let entry of (evidence$ | async)" 
                 class="evidence-entry" 
                 [class]="entry.evidence.verdict"
                 [class.selected]="selectedEntry === entry"
                 (click)="selectEntry(entry)">
              <div class="entry-meta">
                <span class="seq">#{{ entry.sequenceId }}</span>
                <span class="ts">{{ entry.timestamp | date:'HH:mm:ss.SSS' }}</span>
                <span class="type">{{ entry.type }}</span>
              </div>
              <div class="entry-payload">{{ entry.payload }}</div>
              <div class="entry-forensics" *ngIf="selectedEntry === entry">
                <div class="detail-grid">
                  <div class="detail-item"><label>HASH</label><code>{{ entry.evidence.hash }}</code></div>
                  <div class="detail-item"><label>PREV</label><code>{{ entry.evidence.prevHash }}</code></div>
                  <div class="detail-item"><label>SIGNATURE</label><code>{{ entry.evidence.signature }}</code></div>
                  <div class="detail-item"><label>EPOCH</label><code>{{ entry.evidence.epoch }}</code></div>
                </div>
              </div>
            </div>
          </div>
        </section>

        <!-- GOVERNANCE PANEL (Right) -->
        <aside class="side-panel gov-panel">
          <h3>GOVERNANCE STATE</h3>
          <div class="gov-item">
            <label>HSM ANCHOR</label>
            <span class="status-indicator verified">CONNECTED</span>
          </div>
          <div class="gov-item">
            <label>QUORUM</label>
            <span class="status-indicator">3/3 NODES</span>
          </div>
          <div class="gov-item">
            <label>PROPAGATION</label>
            <span class="status-indicator">2ms LATENCY</span>
          </div>

          <div class="impact-assessment" *ngIf="(state$ | async)?.activeDrill !== 'NONE'">
            <h3>IMPACT ASSESSMENT</h3>
            <div class="impact-card">
              <label>BLAST RADIUS</label>
              <div class="radius-indicator" [class.high]="(state$ | async)?.trustLevel === 'UNTRUSTED'">
                {{ (state$ | async)?.trustLevel === 'UNTRUSTED' ? 'CRITICAL' : 'LIMITED' }}
              </div>
              <div class="invariant-check">
